const warehouse = {
  hasInventory: () => false,                                  // canned
  reserve: () => { throw new Error('out of stock'); },
};

const order = new Order('Talisker', 50);
assert.equal(order.fill(warehouse), false);

const warehouse = {
  hasInventory: jest.fn().mockReturnValue(false),
  reserve: jest.fn().mockRejectedValue(new Error('out of stock')),
};

await expect(order.fill(warehouse)).resolves.toBe(false);
